private boolean alwaysReturnsTrue(UMethod method) {
    UExpression body = method.getUastBody();
    if (body instanceof UBlockExpression) {
        List<UExpression> expressions = ((UBlockExpression) body).getExpressions();
        if (expressions.size() == 1) {
            UExpression expr = expressions.get(0);
            return isTrueLiteral(UastUtils.skipParenthesizedExprDown(expr));
        }
    } else if (body != null) {
        return isTrueLiteral(UastUtils.skipParenthesizedExprDown(body));
    }
    return false;
}

private boolean isTrueLiteral(UExpression expr) {
    if (expr instanceof UReturnExpression) {
        return isTrueLiteral(((UReturnExpression) expr).getReturnExpression());
    }
    return expr instanceof ULiteralExpression && Boolean.TRUE.equals(((ULiteralExpression) expr).getValue());
}
```

